type AnyPayload = Record<string, unknown>;

export const webhookHandlers: Record<string, (payload: AnyPayload, req: Request) => Promise<void>> = {
  "inventory_levels/update": async (payload: AnyPayload, _req: Request) => {
    await handleInventoryLevelUpdate(payload as unknown as InventoryLevelUpdatePayload);
  },
  "products/delete": async (payload: AnyPayload, _req: Request) => {
    await handleProductsDelete(payload as unknown as ProductsDeletePayload);
  },
  "orders/paid": async (payload: AnyPayload, _req: Request) => {
    await handleOrdersPaid(payload as unknown as OrdersPaidPayload);
  },
};

